":78250,"source_sha256":"dded3484203526cf5de4f6b77d7b3aa08f2a626597de5247f2f5f3166e00621e","source_published_at":null,"historical_received_at":null,"evidence":{"representation":"EXACT_UNCOMPRESSED_ZIP_MEMBER","archive_member":"SUBMISSION.tsv","archive_sha256":"4761f8614d42dc52892417d3ad5f809309a39573b1f44530aa549c36f2f6593d","archive_bytes":5871882,"archive_local_path":"/workspace/scratch/5db48b32d103/company02/2026q3_ncen.zip","record_filing_dates_are_not_current_archive_receipts":true,"no_original_historical_receipt_inferred":true,"known_archive_limitation":"SEC archive excludes schema3.1 submissions; absence is never an exclusion.","local_file_modified_at":"2026-10-24T03:41:25.124184+00:00","retrieval_clock_basis":"DATABASE_TRANSFER_RECEIPT_IS_NOT_SOURCE_PUBLICATION_OR_ORIGINAL_HISTORICAL_RECEIPT","http_status_observed":200}}]$catalog$::jsonb;
 spec jsonb; c population_top3000_202608_202609_v1.acquisition_control%rowtype;
 existing population_top3000_202608_202609_v1.source_document%rowtype;
 b bigint;h text;request_increment integer;ev jsonb;
BEGIN
 PERFORM population_top3000_202608_202609_v1.ref01_adjudication_controller_v3(false);
 SELECT * INTO STRICT c FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton;
 IF c.owner_id IS DISTINCT FROM p_owner OR c.owner_fence IS DISTINCT FROM p_fence OR c.stop_generation IS DISTINCT FROM p_stop
 OR NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton AND enabled)
 THEN RAISE EXCEPTION 'REF01_NCEN_CURRENT_OWNER_AND_STOP_REQUIRED';END IF;
 SELECT value INTO spec FROM jsonb_array_elements(catalog) WHERE value->>'source_id'=p_source_id;
 IF spec IS NULL THEN RAISE EXCEPTION 'REF01_NCEN_PINNED_SOURCE_REQUIRED';END IF;
 b:=octet_length(p_body);h:=encode(sha256(convert_to(p_body,'UTF8')),'hex');
 IF b IS NULL OR b NOT BETWEEN 1 AND 524288 OR b IS DISTINCT FROM (spec->>'content_bytes')::bigint OR h IS DISTINCT FROM spec->>'source_sha256'
 THEN RAISE EXCEPTION 'REF01_NCEN_EXACT_BYTES_REQUIRED';END IF;
 SELECT * INTO existing FROM population_top3000_202608_202609_v1.source_document WHERE source_id=p_source_id;
 IF FOUND THEN
  IF existing.source_sha256 IS DISTINCT FROM h OR existing.content_bytes IS DISTINCT FROM b OR existing.content_text IS DISTINCT FROM p_body
   OR existing.source_uri IS DISTINCT FROM spec->>'source_uri' OR existing.source_provider IS DISTINCT FROM 'SEC'
   OR existing.historical_received_at IS NOT NULL OR existing.source_published_at IS NOT NULL
  THEN RAISE EXCEPTION 'REF01_NCEN_IMMUTABLE_SOURCE_REPLAY_CONFLICT';END IF;
  RETURN jsonb_build_object('state','REUSED','source_id',p_source_id,'sha256',h,'new_bytes',0);
 END IF;
 request_increment:=CASE WHEN EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.source_document
  WHERE source_provider='SEC' AND source_id LIKE 'ref01-sec-ncen:%' AND evidence->>'archive_sha256'=spec#>>'{evidence,archive_sha256}') THEN 0 ELSE 1 END;
 IF c.stored_bytes+c.reserved_bytes+b>c.max_source_bytes OR c.provider_requests+request_increment>c.max_provider_requests OR c.http_invocations+request_increment>c.max_http_invocations
 THEN RAISE EXCEPTION 'REF01_NCEN_FINITE_OPERATIONAL_BOUND';END IF;
 ev:=spec->'evidence'||jsonb_build_object('scope_sha256',c.scope_sha256,'owner_id',p_owner,'owner_fence',p_fence,'stop_generation',p_stop,
  'import_revision','ref01-ncen-source-import-v4','external_archive_request_count_recorded',request_increment,'external_archive_http_invocations_recorded',request_increment,
  'observed_successful_fetches_per_archive',1,'http_invocation_basis','ONE_OBSERVED_SUCCESSFUL_URLLIB_CLIENT_FETCH_PER_PINNED_ARCHIVE_NO_INFERRED_HISTORICAL_RECEIPT',
  'no_additional_retry_count_inferred',true,
  'source_complete',false,'strict_original_receipt_qualified',false,'archive_is_retained_locally',true,
  'actual_cost_invoice_reconciled',false,'current_database_transfer_at',clock_timestamp());
 INSERT INTO population_top3000_202608_202609_v1.source_document
  (source_id,source_sha256,source_uri,source_provider,retrieved_at,source_published_at,historical_received_at,content_text,content_bytes,evidence,license_policy)
 VALUES(p_source_id,h,spec->>'source_uri','SEC',clock_timestamp(),NULL,NULL,p_body,b,ev,'PUBLIC_SEC_DATA_WITH_SOURCE_ATTRIBUTION');
 UPDATE population_top3000_202608_202609_v1.acquisition_control SET stored_bytes=stored_bytes+b,provider_requests=provider_requests+request_increment,http_invocations=http_invocations+request_increment,
  last_useful_progress_at=clock_timestamp(),updated_at=clock_timestamp() WHERE singleton;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details)
 VALUES('REF01_NCEN_SOURCE_COMMITTED',jsonb_build_object('source_id',p_source_id,'source_sha256',h,'new_bytes',b,
  'external_archive_requests_recorded',request_increment,'external_archive_http_invocations_recorded',request_increment,
  'physical_fetch_evidence','ONE_SUCCESSFUL_RETAINED_ARCHIVE_FETCH; NO_EXTRA_RETRY_COUNT_INFERRED','owner_fence',p_fence,'stop_generation',p_stop,
  'no_network_request_during_import',true,'original_historical_receipt_inferred',false));
 PERFORM population_top3000_202608_202609_v1.ref01_adjudication_controller_v3(false);
 RETURN jsonb_build_object('state','SOURCE_COMMITTED','source_id',p_source_id,'sha256',h,'new_bytes',b,'external_archive_requests_recorded',request_increment);
END $function$;
REVOKE ALL ON FUNCTION population_top3000_202608_202609_v1.ref01_ncen_source_import_v4(text,bigint,bigint,text,text) FROM PUBLIC,anon,authenticated;
